const items = $input.all();
if (items.length < 3) {
  throw new Error(`Le Judge attend 3 résultats agents, reçu ${items.length}.`);
}

const rootCause   = items[0]?.json ?? {};
const security    = items[1]?.json ?? {};
const remediation = items[2]?.json ?? {};

const incidentNode    = $('Extract Project Config');
const fetchedDataNode = $('Merge All Fetched Data');
if (!incidentNode.isExecuted)    throw new Error('Node "Extract Project Config" non exécuté.');
if (!fetchedDataNode.isExecuted) throw new Error('Node "Merge All Fetched Data" non exécuté.');

const incident    = incidentNode.first().json ?? {};
const fetchedData = fetchedDataNode.first().json ?? {};
const enriched    = fetchedData.enrichedData ?? {};

// ── Comptage COMPLET (aucune troncature) ──
const cves         = enriched.trivy?.cves ?? [];
const owaspCves    = enriched.owasp?.cves ?? [];
const criticalCves = cves.filter(c => c.severity === 'CRITICAL').length
                   + owaspCves.filter(c => c.severity === 'CRITICAL').length;
const highCves     = cves.filter(c => c.severity === 'HIGH').length
                   + owaspCves.filter(c => c.severity === 'HIGH').length;

const sonarIssues   = enriched.sonar?.issues ?? [];
const blockers      = sonarIssues.filter(i => i.severity === 'BLOCKER').length;
const criticalVulns = sonarIssues.filter(i => i.severity === 'CRITICAL' && i.type === 'VULNERABILITY').length;
const bugs          = sonarIssues.filter(i => i.type === 'BUG').length;
const codeIssues    = sonarIssues.filter(i => ['BUG', 'VULNERABILITY'].includes(i.type)).length;

const autoFixable     = remediation.autoFixable === true;
const remediationPlan = remediation.fixSteps ?? remediation.steps ?? [];

// ── LOGIQUE DE RECOMMANDATION — SÉCURITÉ D'ABORD ──
let recommendation, requiresApproval = false, reasonCode, reasonText;

if (criticalCves > 0) {
  recommendation = 'BLOCK';
  reasonCode     = 'CRITICAL_CVE';
  reasonText     = `${criticalCves} CVE critique(s) détectée(s) dans le conteneur ou les dépendances. `
                 + `Déploiement à risque : remédiation manuelle requise avant tout merge.`;
}
else if (blockers > 0 || criticalVulns > 0 || bugs > 0) {
  if (autoFixable) {
    recommendation   = 'FIX_PROPOSED';
    requiresApproval = true;
    reasonCode       = 'CODE_FIX_AVAILABLE';
    reasonText       = `${blockers} blocker(s), ${criticalVulns} vulnérabilité(s) critique(s), ${bugs} bug(s) `
                     + `détecté(s) dans le code source. L'agent IA propose une correction automatique. `
                     + `Validation développeur requise avant génération de la Pull Request.`;
  } else {
    recommendation   = 'FIX_PROPOSED';
    requiresApproval = true;
    reasonCode       = 'MANUAL_FIX_RECOMMENDED';
    reasonText       = `${blockers} blocker(s), ${criticalVulns} vulnérabilité(s) critique(s), ${bugs} bug(s) `
                     + `détecté(s). L'agent estime la correction COMPLEXE (autoFixable=false). `
                     + `Un patch IA est proposé mais une revue manuelle approfondie est fortement conseillée.`;
  }
}
else {
  recommendation = 'NOTIFY_ONLY';
  reasonCode     = 'NO_CRITICAL_ISSUE';
  reasonText     = `Aucun problème critique de sécurité ou de code détecté. `
                 + `${codeIssues} issue(s) mineure(s) — aucune action automatique requise.`;
}

// ── Score de sécurité (0 = pire, 100 = sain) ──
const securityScore = Math.max(0, 100
  - criticalCves * 30
  - highCves     * 10
  - blockers     * 12
  - criticalVulns * 8
  - bugs         * 5);

const riskLevel =
  criticalCves > 0 || blockers > 2 ? 'critical'
  : blockers > 0 || criticalVulns > 0 ? 'high'
  : bugs > 0 ? 'medium'
